```python
# 推斷：資料表=上期報價、本期報價（表頭第1列）｜欄位=品號、品名、單價、幣別、計價單位｜主檔=上期報價｜鍵=品號｜篩選=兩表皆存在且對應欄位值不同｜輸出=新工作表「變更明細」
import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)

ws_prev = wb["上期報價"]
ws_curr = wb["本期報價"]

def build_header_map(ws):
    header = {}
    for col_idx, cell in enumerate(ws[1], start=1):
        if cell.value is not None:
            header[cell.value] = col_idx
    return header

header_prev = build_header_map(ws_prev)
header_curr = build_header_map(ws_curr)

compare_cols = ["品名", "單價", "幣別", "計價單位"]

# 以上期報價的列序為「原表列序」
prev_rows = {}
prev_data = {}
for r in range(2, ws_prev.max_row + 1):
    pn = ws_prev.cell(row=r, column=header_prev["品號"]).value
    prev_rows[pn] = r
    prev_data[pn] = {
        col: ws_prev.cell(row=r, column=header_prev[col]).value
        for col in compare_cols
    }

curr_data = {}
for r in range(2, ws_curr.max_row + 1):
    pn = ws_curr.cell(row=r, column=header_curr["品號"]).value
    curr_data[pn] = {
        col: ws_curr.cell(row=r, column=header_curr[col]).value
        for col in compare_cols
    }

changes = []
for pn in prev_data:
    if pn not in curr_data:
        continue
    for col in compare_cols:
        old_val = prev_data[pn][col]
        new_val = curr_data[pn][col]
        if old_val != new_val:
            changes.append((prev_rows[pn], pn, col, old_val, new_val))

# 依原表列序排序
changes.sort(key=lambda x: x[0])

ws_out = wb.create_sheet(title="變更明細")
ws_out.append(["品號", "變更欄位", "舊值", "新值"])
for _, pn, col, old_val, new_val in changes:
    ws_out.append([pn, col, old_val, new_val])

wb.save(OUTPUT_PATH)
```

