# 比對「上月名冊」與「本月名冊」，依員工編號逐欄列出差異到新工作表「名冊變更」
import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)

def read_roster(ws):
    rows = list(ws.iter_rows(values_only=True))
    header = rows[0]
    col_map = {name: idx for idx, name in enumerate(header)}
    data = {}
    order = []
    for row in rows[1:]:
        emp_id = row[col_map['員工編號']]
        if emp_id is None:
            continue
        order.append(emp_id)
        data[emp_id] = {name: row[idx] for name, idx in col_map.items()}
    return header, data, order

last_header, last_data, _ = read_roster(wb['上月名冊'])
this_header, this_data, this_order = read_roster(wb['本月名冊'])

# 以本月名冊的欄位順序為準（兩表欄位相同），排除比對鍵「員工編號」
compare_fields = [f for f in this_header if f != '員工編號']

ws_out = wb.create_sheet(title='名冊變更')
ws_out.append(['員工編號', '變更欄位', '舊值', '新值'])

for emp_id in this_order:
    if emp_id not in last_data:
        continue
    for field in compare_fields:
        old_val = last_data[emp_id].get(field)
        new_val = this_data[emp_id].get(field)
        if old_val != new_val:
            ws_out.append([emp_id, field, old_val, new_val])

wb.save(OUTPUT_PATH)
```

```python
# 推斷：資料表=上月名冊、本月名冊（表頭第1列）｜欄位=時數｜主檔=員工編號｜鍵=員工編號｜篩選=排除員工編號為空的小計/說明列｜輸出=新工作表「時數變動」
import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)

def read_roster(ws):
    headers = [cell.value for cell in ws[1]]
    col_idx = {name: i for i, name in enumerate(headers)}
    data = {}
    for row in ws.iter_rows(min_row=2, values_only=True):
        emp_id = row[col_idx['員工編號']]
        # 跳過小計列、說明列等員工編號為空的列
        if not emp_id:
            continue
        data[emp_id] = {
            'name': row[col_idx['姓名']],
            'hours': row[col_idx['時數']],
        }
    return data

last_month = read_roster(wb['上月名冊'])
this_month = read_roster(wb['本月名冊'])

new_ws_name = '時數變動'
if new_ws_name in wb.sheetnames:
    del wb[new_ws_name]
new_ws = wb.create_sheet(title=new_ws_name)
new_ws.append(['員工編號', '姓名', '舊時數', '新時數'])

for emp_id, old_info in last_month.items():
    if emp_id in this_month:
        new_info = this_month[emp_id]
        if old_info['hours'] != new_info['hours']:
            new_ws.append([
                emp_id,
                new_info['name'],
                old_info['hours'],
                new_info['hours'],
            ])

wb.save(OUTPUT_PATH)
```

```python
# 推斷：資料表=系統帳（表頭第1列）、實盤（表頭第1列）｜欄位=料號、品名、數量｜主檔=系統帳｜鍵=料號｜篩選=數量不相等｜輸出=新工作表「數量差異」
import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)

# 讀取「系統帳」
sys_ws = wb["系統帳"]
sys_headers = {cell.value: idx for idx, cell in enumerate(sys_ws[1], start=1)}
sys_data = {}
for row in sys_ws.iter_rows(min_row=2, values_only=True):
    mat = row[sys_headers["料號"] - 1]
    if not mat:
        continue
    sys_data[mat] = {
        "品名": row[sys_headers["品名"] - 1],
        "數量": row[sys_headers["數量"] - 1],
    }

# 讀取「實盤」
phy_ws = wb["實盤"]
phy_headers = {cell.value: idx for idx, cell in enumerate(phy_ws[1], start=1)}
phy_data = {}
for row in phy_ws.iter_rows(min_row=2, values_only=True):
    mat = row[phy_headers["料號"] - 1]
    if not mat:
        continue
    phy_data[mat] = {
        "品名": row[phy_headers["品名"] - 1],
        "數量": row[phy_headers["數量"] - 1],
    }

# 建立新工作表
new_ws = wb.create_sheet(title="數量差異")
new_ws.append(["料號", "品名", "舊數量", "新數量"])

# 以系統帳為主檔，比對實盤數量；也處理實盤有但系統帳沒有的料號
all_mats = set(sys_data.keys()) | set(phy_data.keys())
for mat in sorted(all_mats):
    sys_qty = sys_data.get(mat, {}).get("數量")
    phy_qty = phy_data.get(mat, {}).get("數量")
    # 只列出數量不一致的項目
    if sys_qty != phy_qty:
        name = sys_data.get(mat, {}).get("品名") or phy_data.get(mat, {}).get("品名")
        new_ws.append([mat, name, sys_qty, phy_qty])

wb.save(OUTPUT_PATH)
```

```python
# 推斷：資料表=系統帳、實盤（表頭第1列）｜欄位=料號、品名、數量｜主檔=系統帳｜鍵=料號｜篩選=排除小計與說明列，且兩表數量不相等｜輸出=新工作表「數量變動」
import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)

def read_inventory(ws):
    # 建立欄名 -> 欄位索引（1-based）對照
    header = {}
    for cell in ws[1]:
        if cell.value is not None:
            header[cell.value] = cell.column

    col_pn = header.get("料號")
    col_name = header.get("品名")
    col_qty = header.get("數量")

    data = {}
    for row in ws.iter_rows(min_row=2, values_only=True):
        pn = row[col_pn - 1] if col_pn else None
        name = row[col_name - 1] if col_name else None
        qty = row[col_qty - 1] if col_qty else None

        # 排除小計列、說明列及空料號列
        if not pn:
            continue
        if isinstance(name, str) and ("小計" in name or name.startswith("（")):
            continue

        # 數量轉為數值
        try:
            qty = int(qty)
        except Exception:
            try:
                qty = float(qty)
            except Exception:
                qty = None

        data[pn] = {"品名": name, "數量": qty}

    return data

sys_data = read_inventory(wb["系統帳"])
act_data = read_inventory(wb["實盤"])

# 比對兩表數量，以系統帳為舊數量、實盤為新數量
diff_rows = []
for pn, sys_info in sys_data.items():
    act_info = act_data.get(pn)
    if act_info is None:
        continue
    if sys_info["數量"] != act_info["數量"]:
        diff_rows.append([
            pn,
            sys_info["品名"],
            sys_info["數量"],
            act_info["數量"],
        ])

# 建立新工作表並寫入結果
ws_out = wb.create_sheet(title="數量變動")
ws_out.append(["料號", "品名", "舊數量", "新數量"])
for row in diff_rows:
    ws_out.append(row)

wb.save(OUTPUT_PATH)
```
